{
  "problem": "Recruit 5-10 frontend developers between jobs to complete a full course module on elegantfrontend.training, collect structured feedback on lesson clarity, practice dashboard usability, and perceived value, and document the results in a beta test report at docs/beta-report.md, verifying with `python3 .benzene/checks/material.py beta` passing.",
  "steps": [
    {
      "office": "cmo",
      "step": "Create a recruitment post for beta testers targeting frontend developers between jobs. Publish on LinkedIn, X, and Instagram with a link to a simple signup form (Google Form or similar) that collects: name, email, years of experience, current situation (laid off, seeking), preferred course module (UI, State, Server, Agent Skills), and availability over the next 2 weeks. Use the CXO's audience personas (P1-P4 from ux-model.md) to target the right people.",
      "after": [],
      "acceptance": [
        {
          "text": "Recruitment posts published on at least 3 channels with signup form link",
          "check": {"type": "verifier", "name": "manual"}
        }
      ]
    },
    {
      "office": "cxo",
      "step": "Review signup responses and select 5-10 participants representing a mix of personas (P1-P4). Send each participant a welcome email with: assigned course module (one of the four free courses), access instructions (no signup required, direct links to lessons), a feedback template (Google Form or Notion) with structured questions on lesson clarity (1-5 scale + open text), practice dashboard usability (1-5 scale + open text), perceived value (1-5 scale + open text), and overall NPS. Set a 2-week deadline for completion.",
      "after": [0],
      "acceptance": [
        {
          "text": "5-10 participants confirmed with assigned modules and feedback template sent",
          "check": {"type": "verifier", "name": "manual"}
        }
      ]
    },
    {
      "office": "cto",
      "step": "Confirm that all lessons, practice questions, and dashboard progress tracking work for the selected modules without authentication. Fix any blocking issues before beta start.",
      "after": [0],
      "acceptance": [
        {
          "text": "All lessons, practice questions, and dashboard progress tracking work for the selected modules without authentication",
          "check": {"type": "verifier", "name": "manual"}
        }
      ]
    },
    {
      "office": "cxo",
      "step": "Collect completed feedback forms from participants after the 2-week period. Send reminder emails at day 7 and day 13. Compile responses into a structured dataset (CSV or JSON) with participant persona, module, and all feedback fields.",
      "after": [1, 2],
      "acceptance": [
        {
          "text": "Feedback collected from at least 5 participants with complete structured responses",
          "check": {"type": "verifier", "name": "manual"}
        }
      ]
    },
    {
      "office": "cxo",
      "step": "Write the beta test report at docs/beta-report.md with: executive summary, participant demographics (anonymized), module completion rates, quantitative feedback scores (averages per category), qualitative feedback themes, severity classification of issues (blocker/major/minor/none), and prioritized recommendations for the roadmap. Include a changelog entry linking to the report.",
      "after": [3],
      "acceptance": [
        {
          "text": "docs/beta-report.md exists with all required sections and a changelog entry linking to it",
          "check": {"type": "verifier", "name": "manual"}
        }
      ]
    },
    {
      "office": "cxo",
      "step": "Create beta report files in .benzene/material/experience/beta/ for each CTO change that is in 'review' stage (per .benzene/changes.json). Each report must follow the format in .benzene/material/experience/beta/README.md with change ID, title, persona (P1-P4), tasks (3-5), passed, failed, and severity (none/minor/major/blocker).",
      "after": [4],
      "acceptance": [
        {
          "text": "All required beta report files exist for CTO changes in review",
          "check": {"type": "verifier", "name": "manual"}
        }
      ]
    }
  ]
}
